mapper.select:
SELECT distinct s.school_id, s.school_head, s.school_name, s.school_province, s.school_address, s.rank_list, s.score, s.ruanke_rank FROM tb_school AS s JOIN tb_province as p ON s.school_id = p.school_id JOIN tb_year as y ON p.province_id = y.province_id JOIN tb_category as c ON y.year_id = c.year_id JOIN tb_batch as b ON c.category_id = b.category_id JOIN tb_score as sc ON b.batch_id = sc.batch_id
AND s.school_province = #{province}
AND (
s.rank_list LIKE CONCAT('%', #{item}, '%')
)
order by s.score desc

select c.comment_id, u.username, u.head, c.comment, c.add_time
from tb_comment AS c,
     tb_user AS u
where c.school_id = #{schoolId}
  and u.id = c.user_id
